const navButton=(scope,key,label,active=false)=>`<button class="btn${active?' primary':''}" type="button" data-jl-nav="${scope}" data-jl-key="${key}" aria-pressed="${active}" onclick="jaguarLifecycle.switchTab('${scope}','${key}')">${E(label)}</button>`;
