function switchTab(scope,key){const root=document.getElementById('jl_workspace');if(!root)return;for(const el of root.querySelectorAll('[data-jl-panel="'+scope+'"]'))el.hidden=el.dataset.jlKey!==key;for(const el of root.querySelectorAll('[data-jl-nav="'+scope+'"]')){const active=el.dataset.jlKey===key;el.setAttribute('aria-pressed',String(active));el.classList.toggle('primary',active);}if(scope==='edit'){const submit=document.getElementById('jl_submit'),review=document.getElementById('jl_review');if(submit)submit.hidden=key!=='save';if(review)review.hidden=key==='save';if(key==='save')refreshReview();}}
function reveal(field){const parents=[];for(let p=field;p;p=p.parentElement){if(p.tagName==='DETAILS')p.open=true;if(p.dataset.jlPanel)parents.unshift(p);}for(const p of parents)switchTab(p.dataset.jlPanel,p.dataset.jlKey);field.scrollIntoView?.({block:'center'});field.focus();}
function markDirty(e){if(e?.target?.closest('#jl_form')&&e.target.id!=='jl_preview_grade'){if(e.target.closest('#jl_curriculum'))closeFusion();if(!e.target.closest('#jl_fusion'))dirty=true;}}
function subjectMode(){if(pending)return;if(dirty&&!confirm('Hay cambios sin guardar en la planificación. ¿Salir hacia evaluación por materia?'))return;loadPage('modo_materia_360');}
const wizard=[['structure',0,2,'1. Ciclo y calendario'],['subjects',0,0,'2. Asignaturas'],['grades',2,10,'3. Evaluación'],['attendance',10,17,'4. Asistencia'],['regularization',17,28,'5. Regularización'],['continuity',28,36,'6. Continuidad'],['schedule',36,fields.length,'7. Horarios']];
async function api(method='GET',body=null,c=''){
 const {data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw Error('Inicia sesión de nuevo.');
 const r=await fetch('/api/academic-lifecycle'+(c?'?cycle='+encodeURIComponent(c):''),{method,headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await jaguarReadJson(r);if(!r.ok||!d.ok)throw Error(d.error||'No se pudo completar la operación.');return d.data;
}
function controls(policy){const rendered=fields.map(([k,label,def,type,a,b])=>{
 const v=policy[k]??def,id='jl_'+k;
 if(type==='bool')return `<label class="block text-sm"><input id="${id}" type="checkbox" ${v?'checked':''}> ${E(label)}</label>`;
 let input=Array.isArray(type)?`<select id="${id}" class="input" required><option value="">Selecciona</option>${type.map((o,i)=>`<option value="${E(o)}" ${String(o)===String(v)?'selected':''}>${E(a[i])}</option>`).join('')}</select>`:`<input class="input" id="${id}" type="${type}" value="${E(v)}" ${type==='number'?`min="${a}" max="${b}" step="${['recoveryCap','recourseCap','attendancePct','points','repeatThreshold'].includes(k)?'any':'1'}"`:'maxlength="80"'} required ${k==='periods'?'onchange="jaguarLifecycle.calendar()"':''}>`;
 return `<label class="block text-sm">${E(label)}${input}</label>`;
 });return Object.fromEntries(wizard.map(([key,a,b])=>[key,`<div class="grid md:grid-cols-2 gap-3">${rendered.slice(a,b).join('')}</div>`]))}
function calendarHtml(n,old=[]){return Array.from({length:n},(_,i)=>`<div class="grid grid-cols-2 gap-2"><label class="text-sm">Inicio P${i+1}<input class="input" type="date" id="jl_start${i}" value="${E(old[i]?.start)}" required></label><label class="text-sm">Fin P${i+1}<input class="input" type="date" id="jl_end${i}" value="${E(old[i]?.end)}" required></label></div>`).join('')}
function captureCalendar(){return Array.from({length:6},(_,i)=>({start:document.getElementById('jl_start'+i)?.value||'',end:document.getElementById('jl_end'+i)?.value||''}))}
function calendar(){const n=Number(document.getElementById('jl_periods')?.value);if(Number.isInteger(n)&&n>=1&&n<=6&&document.querySelectorAll('#jl_calendar input[type=date]').length!==n*2){const old=captureCalendar(),subjects=captureCurriculum();if(subjects.some(r=>r.periodMinutes.slice(n).some(v=>v!==0)||r.periodAttendancePct.slice(n).some(v=>v!==null))&&!confirm('Se quitarán las cargas de los periodos retirados de esta propuesta. ¿Continuar?')){document.getElementById('jl_periods').value=String(document.querySelectorAll('#jl_calendar input[type=date]').length/2);return;}document.getElementById('jl_calendar').innerHTML=calendarHtml(n,old);renderCurriculum(subjects)}}
// A proposed curriculum belongs to the same version as the policy and calendar.
