function curriculumRows(n,items=[]){return items.map((r,i)=>{
 const num=(k,label,v,lo,hi,optional=false)=>`<label class="text-sm">${E(label)}<input data-field="${k}" class="input" type="number" min="${lo}" max="${hi}" step="${k.toLowerCase().includes('attendancepct')?'any':'1'}" value="${E(v??'')}" ${optional?'':'required'}></label>`;
 const select=(k,label,v,opts)=>`<label class="text-sm">${E(label)}<select data-field="${k}" class="input">${opts.map(([value,label])=>`<option value="${E(value)}" ${String(value)===String(v)?'selected':''}>${E(label)}</option>`).join('')}</select></label>`;
 return `<details class="card space-y-2" data-curriculum-row data-key="${E(r.key)}" ${!r.name?'open':''}><summary class="cursor-pointer font-bold">${E(r.name||`Asignatura ${i+1}`)} · ${E(r.grade)}°</summary><div class="mt-3 space-y-2"><div class="grid md:grid-cols-2 gap-2"><label>Nombre<input data-field="name" class="input" value="${E(r.name)}" minlength="2" maxlength="120" required></label>${select('grade','Grado',r.grade,[[1,'Primero'],[2,'Segundo'],[3,'Tercero']])}<label>Referencia del catálogo (opcional)<input data-field="legacyId" class="input" pattern="[1-9][0-9]{0,18}" value="${E(r.legacyId)}"></label>${select('evaluation','Evaluación',r.evaluation,[['numerica','Numérica'],['cualitativa','AP/RP'],['no_aplica','Sin evaluación']])}${select('qualitativeMode','Criterio si es AP/RP',r.qualitativeMode||'all',[['all','Todos los periodos AP'],['final','Resultado final autorizado']])}<label><input data-field="required" type="checkbox" ${r.required?'checked':''}> Obligatoria para acreditar el grado</label>${num('sessionMinutes','Minutos por sesión',r.sessionMinutes,1,240)}${num('dailyMin','Mínimo diario (min)',r.dailyMin??0,0,1440)}${num('dailyMax','Máximo diario (min)',r.dailyMax,1,1440)}${num('weeklyMinutes','Referencia semanal (min)',r.weeklyMinutes,0,10080)}${num('monthlyMinutes','Referencia mensual (min)',r.monthlyMinutes,0,44640)}${select('distribution','Distribución',r.distribution,[['fixed','Fija'],['flexible','Flexible']])}${select('shortfall','Déficit de horas',r.shortfall,[['block','Bloquear cierre'],['resolution','Resolución documentada']])}${num('totalMinutes','Total exigido en el ciclo (min)',r.totalMinutes,1,525600)}${num('attendancePct','Asistencia mínima propia (%) · vacío hereda ciclo',r.attendancePct,0,100,true)}</div><h4>Distribución por periodo</h4><div class="grid md:grid-cols-2 gap-2">${Array.from({length:n},(_,j)=>num('periodMinutes'+j,`P${j+1} · minutos`,r.periodMinutes?.[j]??0,0,525600)+num('periodAttendancePct'+j,`P${j+1} · mínimo asistencia (%)`,r.periodAttendancePct?.[j],0,100,true)).join('')}</div><p data-curriculum-total class="text-sm"></p><button class="btn" type="button" onclick="jaguarLifecycle.matchTotal(this)">Usar suma de periodos como total</button> <button type="button" class="btn" onclick="jaguarLifecycle.removeSubject(${i})">Retirar de esta propuesta</button></div></details>`;
 }).join('')}
function captureCurriculum(){return [...document.querySelectorAll('#jl_curriculum [data-curriculum-row]')].map(el=>{
 const get=k=>el.querySelector('[data-field="'+k+'"]'),str=k=>get(k)?.value??'',num=k=>Number(str(k)),optional=k=>str(k)===''?null:num(k);
 return {key:el.dataset.key,name:str('name'),grade:num('grade'),legacyId:str('legacyId')||null,evaluation:str('evaluation'),qualitativeMode:str('evaluation')==='cualitativa'?str('qualitativeMode'):null,required:get('required').checked,sessionMinutes:num('sessionMinutes'),dailyMin:num('dailyMin'),dailyMax:num('dailyMax'),weeklyMinutes:num('weeklyMinutes'),monthlyMinutes:num('monthlyMinutes'),distribution:str('distribution'),shortfall:str('shortfall'),totalMinutes:num('totalMinutes'),attendancePct:optional('attendancePct'),periodMinutes:[...el.querySelectorAll('[data-field^="periodMinutes"]')].map(e=>Number(e.value)),periodAttendancePct:[...el.querySelectorAll('[data-field^="periodAttendancePct"]')].map(e=>e.value===''?null:Number(e.value))};
 })}
function matchTotal(button){dirty=true;const row=button.closest('[data-curriculum-row]');row.querySelector('[data-field="totalMinutes"]').value=String([...row.querySelectorAll('[data-field^="periodMinutes"]')].reduce((a,e)=>a+Number(e.value||0),0));curriculumTotals();}
function curriculumTotals(){for(const el of document.querySelectorAll('#jl_curriculum [data-curriculum-row]')){const total=[...el.querySelectorAll('[data-field^="periodMinutes"]')].reduce((a,e)=>a+Number(e.value||0),0),target=Number(el.querySelector('[data-field="totalMinutes"]').value||0);el.querySelector('summary').textContent=(el.querySelector('[data-field="name"]').value||'Asignatura nueva')+' · '+el.querySelector('[data-field="grade"]').value+'°';el.querySelector('[data-curriculum-total]').textContent=`Distribución: ${total} min (${(total/60).toFixed(2)} h reloj) · ${total===target?'coincide con el objetivo':`diferencia ${target-total} min`}`;}}
function renderCurriculum(items){const fusion=document.getElementById('jl_fusion');if(fusion){fusion.hidden=true;fusion.innerHTML='';}const node=document.getElementById('jl_curriculum');if(!node)return;node.innerHTML=curriculumRows(Number(document.getElementById('jl_periods').value),items);curriculumTotals()}
function addSubject(fromCatalog=false){const items=captureCurriculum();if(items.length>=300){toast('Máximo 300 asignaciones.');return;}const m=fromCatalog?catalog.find(x=>String(x.id)===document.getElementById('jl_catalog_select')?.value):null;if(fromCatalog&&!m){toast('Selecciona una materia.');return;}const grade=Number(m?.grado||m?.grados?.[0]||1);let key;do{key='MAT-'+Date.now().toString(36).toUpperCase()+'-'+(++nextKey)}while(items.some(r=>r.key===key));dirty=true;items.push({key,name:m?.nombre||'',legacyId:m?String(m.id):null,grade,evaluation:'numerica',required:true,sessionMinutes:60,dailyMin:0,dailyMax:120,weeklyMinutes:0,monthlyMinutes:0,totalMinutes:0,distribution:'flexible',shortfall:'resolution',periodMinutes:[],periodAttendancePct:[],attendancePct:null});renderCurriculum(items);const added=document.querySelectorAll('#jl_curriculum [data-curriculum-row]');if(added.length)added[added.length-1].open=true;}
function removeSubject(i){const items=captureCurriculum();if(!confirm('¿Retirar esta asignatura de la nueva propuesta? Las versiones anteriores y la materia activa no cambian.'))return;dirty=true;items.splice(i,1);renderCurriculum(items)}
async function loadCatalog(){const target=document.getElementById('jl_catalog');if(!target)return;target.textContent='Consultando…';try{const {data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw Error('Inicia sesión de nuevo.');const r=await fetch('/api/academic-lifecycle?view=curriculum_catalog',{headers:{Authorization:'Bearer '+session.access_token}}),d=await jaguarReadJson(r);if(!r.ok||!d.ok)throw Error(d.error||'No se pudo consultar el catálogo.');if(!target.isConnected)return;catalog=d.data;target.innerHTML=`<label>Materia existente<select id="jl_catalog_select" class="input"><option value="">Selecciona</option>${catalog.map(m=>`<option value="${E(m.id)}">${E(m.nombre)}${m.grado?` · ${E(m.grado)}°`:""}</option>`).join('')}</select></label><button type="button" class="btn" onclick="jaguarLifecycle.addSubject(true)">Agregar materia del catálogo</button><p class="text-sm">Revisa el grado, la evaluación y la carga de cada materia: no se supone la duración de las horas del catálogo antiguo.</p>`}catch(e){if(target.isConnected)target.textContent=e.message}}
// Create an explicit draft-only union, retaining origin IDs in the proposal reason.
function fusionEditor(){const el=document.getElementById('jl_fusion');if(!el||!writable())return;const list=captureCurriculum();el.hidden=false;el.innerHTML=`<div class="card space-y-2"><h4>Preparar unión de asignaturas (borrador)</h4><p>Selecciona asignaturas numéricas del mismo grado con criterios idénticos. La propuesta sumará sus minutos y creará una asignatura nueva sin vínculo automático al catálogo. Los registros vigentes no cambian.</p><div class="space-y-2">${list.map((m,i)=>`<label class="block"><input type="checkbox" data-jl-fusion="${i}" ${m.evaluation!=='numerica'?'disabled':''}> ${E(m.name||'Sin nombre')} · ${E(m.grade)}° (${E(m.totalMinutes)} min)</label>`).join('')}</div><label>Nombre de la nueva materia<input class="input" id="jl_fusion_name" maxlength="120" placeholder="Nombre de la materia unificada"></label><button type="button" class="btn primary" onclick="jaguarLifecycle.applyFusionDraft()">Preparar propuesta de unión</button> <button type="button" class="btn" onclick="jaguarLifecycle.closeFusion()">Cancelar</button><p id="jl_fusion_status" role="status" class="text-sm"></p></div>`;}
function closeFusion(){const el=document.getElementById('jl_fusion');if(el){el.hidden=true;el.innerHTML='';}}
function applyFusionDraft(){const el=document.getElementById('jl_fusion_status');if(!el||!writable()||pending)return;try{const all=captureCurriculum(),indices=[...document.querySelectorAll('#jl_fusion [data-jl-fusion]:checked')].map(x=>Number(x.dataset.jlFusion)),origins=indices.map(i=>all[i]),name=document.getElementById('jl_fusion_name').value.trim();if(origins.length<2)throw Error('Selecciona por lo menos dos asignaturas.');if(name.length<2||name.length>120||/[\x00-\x1f]/.test(name))throw Error('Indica un nombre válido.');const first=origins[0];if(origins.some(m=>m.grade!==first.grade||m.evaluation!=='numerica'))throw Error('La unión guiada requiere materias numéricas del mismo grado.');const policyKeys=['required','sessionMinutes','distribution','shortfall','attendancePct','periodAttendancePct'];if(origins.some(m=>policyKeys.some(k=>JSON.stringify(m[k])!==JSON.stringify(first[k]))))throw Error('Las materias tienen criterios o sesiones distintos. Concílialos primero sin perder los valores originales.');const existing=all.filter((_,i)=>!indices.includes(i));if(existing.some(m=>m.grade===first.grade&&normalize(m.name.trim())===normalize(name)))throw Error('Ya existe otra materia con ese nombre en el grado.');const n=Number(document.getElementById('jl_periods').value);if(origins.some((m,i)=>{const row=document.querySelectorAll('#jl_curriculum [data-curriculum-row]')[indices[i]];return !m.name.trim()||m.periodMinutes.length!==n||m.periodMinutes.reduce((a,b)=>a+b,0)!==m.totalMinutes||m.totalMinutes<1||[...row.querySelectorAll('input,select')].some(f=>!f.checkValidity());}))throw Error('Completa y concilia las cargas y campos de cada materia origen antes de unirlas.');const sum=k=>origins.reduce((a,m)=>a+m[k],0);const periodMinutes=Array.from({length:n},(_,i)=>origins.reduce((a,m)=>a+m.periodMinutes[i],0));const totalMinutes=sum('totalMinutes'),weeklyMinutes=sum('weeklyMinutes'),monthlyMinutes=sum('monthlyMinutes'),dailyMin=sum('dailyMin'),dailyMax=sum('dailyMax');if(totalMinutes>525600||weeklyMinutes>10080||monthlyMinutes>44640||dailyMax>1440||dailyMin>dailyMax||(first.distribution==='fixed'&&weeklyMinutes===0))throw Error('La suma rebasa los límites de carga del plan. Revisa la distribución y las horas.');const reason=document.getElementById('jl_reason'),trace=`Unión propuesta (grado ${first.grade}): ${origins.map(m=>m.name+' ['+m.key+(m.legacyId?', catálogo '+m.legacyId:'')+']').join(' + ')} → ${name}. Sin traslado de notas ni fusión del catálogo vigente.`;const nextReason=[reason.value.trim(),trace].filter(Boolean).join('\n');if(nextReason.length>1500)throw Error('El motivo excedería 1500 caracteres. Reduce el texto del motivo o el número de orígenes.');if(!confirm('¿Sustituir únicamente estas materias dentro del borrador por '+name+'? La propuesta conservará la referencia de origen en el motivo. No se modificarán notas ni materias vigentes.'))return;let key;do{key='MAT-'+Date.now().toString(36).toUpperCase()+'-'+(++nextKey)}while(all.some(m=>m.key===key));const merged={...first,key,name,legacyId:null,periodMinutes,totalMinutes,weeklyMinutes,monthlyMinutes,dailyMin,dailyMax};fusionSnapshot={form:document.getElementById('jl_form'),items:all,reason:reason.value,n};dirty=true;reason.value=nextReason;renderCurriculum([...existing,merged]);const last=[...document.querySelectorAll('#jl_curriculum [data-curriculum-row]')].at(-1);if(last)last.open=true;const msg=document.getElementById('jl_fusion_notice');if(msg)msg.innerHTML='<p>Unión preparada únicamente en el borrador. Revisa todos los campos, vincula la materia cuando corresponda y registra la propuesta; no se trasladan notas.</p><button type="button" class="btn" onclick="jaguarLifecycle.undoFusionDraft()">Deshacer última preparación</button>'; }catch(e){el.textContent=e.message;}}
function undoFusionDraft(){const t=fusionSnapshot,form=document.getElementById('jl_form');if(!t||form!==t.form||pending)return;if(Number(document.getElementById('jl_periods').value)!==t.n){toast('Cambió el número de periodos; no se puede restaurar de forma segura.');return;}if(!confirm('¿Restaurar todas las asignaturas y el motivo anteriores a la unión? Se descartan los cambios realizados en esos campos desde la preparación.'))return;renderCurriculum(t.items);document.getElementById('jl_reason').value=t.reason;fusionSnapshot=null;dirty=true;document.getElementById('jl_fusion_notice').textContent='Se restauraron las asignaturas y el motivo anteriores.';}
function editor(){const latest=rows[0],p=draft?.policy||latest?.plan?.policy||defaults();version=latest?.version||0;const c=controls(p);
 const history=rows.map(r=>`<details class="card"><summary>V${Number(r.version)} · ${E(r.estado)} · ${E(r.actor_nombre)} (${E(r.actor_cargo)})</summary><p>${E(r.creado_at)} · ${E(r.motivo)}</p><details><summary>Datos técnicos de esta versión</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${E(JSON.stringify(r.plan,null,2))}</pre></details></details>`).join('');
 const base=writable()&&!latest?`<details class="card"><summary>Partir de un ciclo anterior (opcional)</summary><label>Ciclo anterior autorizado<input id="jl_source" class="input" placeholder="2025-2026" pattern="[0-9]{4}-[0-9]{4}"></label><button class="btn" type="button" onclick="jaguarLifecycle.copyTemplate()">Usar como plantilla</button> <button class="btn" type="button" onclick="jaguarLifecycle.resetTemplate()">Comenzar desde cero</button><p id="jl_template_status" class="text-sm"></p><p>No copia expedientes, notas, asistencias, fechas, grupos ni horarios activos.</p></details>`:'';
 const sections={structure:`<h3>Calendario y estructura</h3>${c.structure}<div id="jl_calendar">${calendarHtml(p.periods,draft?.calendar||latest?.plan?.calendar)}</div>`,subjects:`<h3>Plan de estudios</h3><button type="button" class="btn" onclick="jaguarLifecycle.go('union')">Unir materias · simular equivalencia</button> <button type="button" class="btn" onclick="jaguarLifecycle.fusionEditor()">Preparar unión en esta propuesta</button><div id="jl_fusion" hidden></div><div id="jl_fusion_notice" aria-live="polite"></div><p class="text-sm">Configura la carga del ciclo propuesto. Para cambiar solo la evaluación de una materia vigente, utiliza el módulo independiente.</p><button class="btn" type="button" onclick="jaguarLifecycle.subjectMode()">Modo de evaluación por materia</button><div class="flex flex-wrap gap-2"><button type="button" class="btn primary" onclick="jaguarLifecycle.addSubject()">Agregar asignatura nueva</button><button type="button" class="btn" onclick="jaguarLifecycle.loadCatalog()">Consultar materias existentes</button></div><div id="jl_catalog"></div><div id="jl_curriculum" class="space-y-3" oninput="jaguarLifecycle.curriculumTotals()">${curriculumRows(p.periods,draft?.curriculum||latest?.plan?.curriculum||[])}</div>`,grades:`<h3>Evaluación ordinaria</h3>${c.grades}<details class="card"><summary>Comprobar precisión con un ejemplo</summary><label>Nota de ejemplo <input id="jl_preview_grade" type="number" min="0" max="10" step="any" value="9.25" class="input"></label><button class="btn" type="button" onclick="jaguarLifecycle.previewPrecision()">Comparar precisión</button><div id="jl_preview_result" aria-live="polite"></div><p class="text-sm">No guarda notas.</p></details>`,attendance:`<h3>Reglas de asistencia</h3>${c.attendance}`,regularization:`<h3>Recuperación y recursamiento</h3>${c.regularization}`,continuity:`<h3>Continuidad escolar</h3>${c.continuity}`,schedule:`<h3>Horarios y nombres de grupos</h3>${c.schedule}<p class="text-sm">Usa las variables entre llaves para generar nombres.</p><button type="button" class="btn" onclick="jaguarLifecycle.resetNaming()">Restablecer nombres de grupos</button><p id="jl_naming_status" aria-live="polite"></p>`};
 const form=writable()?`<form class="card space-y-3" id="jl_form" novalidate oninput="jaguarLifecycle.markDirty(event)" onchange="jaguarLifecycle.markDirty(event)" onsubmit="jaguarLifecycle.save(event)"><p class="text-sm">${templateOrigin?`Plantilla: ${E(templateOrigin.cycle)} · V${Number(templateOrigin.version)}. Revisa criterios, fechas y jornada.`:'Sin plantilla de ciclo anterior.'}</p><nav class="jl-nav" aria-label="Secciones del plan">${wizard.map(([key,,,label],i)=>navButton('edit',key,label,i===0)).join('')}${navButton('edit','save','8. Revisar y guardar')}</nav>${wizard.map(([key],i)=>panel('edit',key,`<div class="space-y-3">${sections[key]}</div><div class="jl-nav">${i?jumpButton(wizard[i-1][0],'← Anterior'):''}${jumpButton(wizard[i+1]?.[0]||'save','Siguiente →')}</div>`,i===0)).join('')}${panel('edit','save',`<h3>Registrar propuesta</h3><div id="jl_review_summary" class="card text-sm" aria-live="polite"></div><p>Se conserva una nueva versión del plan; no se activa el ciclo ni se modifican notas por este guardado.</p><label>Motivo de la propuesta<textarea id="jl_reason" class="input" minlength="15" maxlength="1500" required></textarea></label>`)}<div id="jl_save_status" role="status" aria-live="polite" tabindex="-1" class="text-sm"></div><div class="jl-nav"> <button class="btn primary" id="jl_review" type="button" onclick="jaguarLifecycle.reviewOrSave()">Revisar / guardar propuesta</button><button class="btn primary" id="jl_submit" type="submit" hidden>Registrar nueva propuesta</button></div></form>`:'';
 return `<div class="card space-y-2"><h3>Planificación ${E(cycle)} · V${version}</h3><p>${latest?'Última versión: '+E(latest.estado):'Sin propuesta registrada.'}</p><p class="text-sm">${writable()?'Edita las secciones que necesites.':'Tu cargo permite consultar las versiones; Dirección y Coordinación preparan propuestas.'}</p></div>${base}${form}${S.role==='direccion_escolar'&&latest?.estado==='propuesta'?`<div class="card"><button class="btn primary" onclick="jaguarLifecycle.approve()">Validar propuesta para planificación</button><p class="text-sm">Requiere otra persona distinta de quien presentó la propuesta. No activa el ciclo.</p></div>`:''}<details class="card" ${writable()?'':'open'}><summary>Historial de versiones (${rows.length})</summary>${history||'<p>Sin versiones.</p>'}</details>`}
function refreshReview(){const target=document.getElementById('jl_review_summary');if(!target)return;const policy=readPolicy(),subjects=captureCurriculum();const dated=captureCalendar().slice(0,policy.periods).filter(x=>x.start&&x.end).length;target.textContent=`Ciclo ${cycle} · ${dated}/${policy.periods} periodos con fechas · ${subjects.length} asignaturas · Mínima aprobatoria ${policy.minimum} · Jornada ${policy.scheduleModel==='fixed'?'Fija':policy.scheduleModel==='flexible'?'Flexible':'Sin seleccionar'}. Se verificará la totalidad del formulario antes de guardar.`;}
function reviewOrSave(){switchTab('edit','save');document.getElementById('jl_reason')?.focus();}
async function open(e){e.preventDefault();if(pending)return;if(dirty&&!confirm('Hay cambios sin guardar. ¿Cargar otro plan y descartar esos cambios?')){document.getElementById('jl_cycle').value=cycle;requestedSection=null;return;}const reqRevision=++revision,c=document.getElementById('jl_cycle').value.trim();const target=document.getElementById('jl_editor');target.textContent='Consultando…';try{const d=await api('GET',null,c);if(!target.isConnected||reqRevision!==revision)return;cycle=c;rows=d.rows||[];templateOrigin=rows[0]?.plan?.template||null;draft=null;dirty=false;target.innerHTML=editor();curriculumTotals();switchTab('main','plan');if(requestedSection&&writable())switchTab('edit',requestedSection);requestedSection=null}catch(err){if(target.isConnected&&reqRevision===revision)target.textContent=err.message}}
function readPolicy(){return Object.fromEntries(fields.map(([k,_,v,t])=>{const el=document.getElementById('jl_'+k);return[k,t==='bool'?el.checked:t==='number'||typeof v==='number'?Number(el.value):el.value]}))}
async function previewPrecision(){const target=document.getElementById('jl_preview_result'),raw=document.getElementById('jl_preview_grade');if(!target||!raw||!raw.reportValidity()||raw.value==='')return;target.textContent='Calculando…';try{const r=await api('POST',{action:'preview_precision',raw:Number(raw.value),policy:readPolicy()});if(target.isConnected)target.innerHTML=`<p><b>Ordinario:</b> ${E(r.ordinary)} · <b>Recuperación:</b> ${E(r.recovery??r.recoveryReview)} · <b>Recursamiento:</b> ${E(r.recourse??r.recourseReview)}.</p>`;}catch(e){if(target.isConnected)target.textContent=e.message}}
// Keep the errors next to the save button; native validity bubbles may be off-screen.
function saveStatus(form,message,issues=[]){
 const status=form.querySelector('#jl_save_status');if(!status||!form.isConnected)return;
 status.replaceChildren();const heading=document.createElement('p');heading.textContent=message;heading.style.fontWeight='bold';status.append(heading);
 if(issues.length){const list=document.createElement('ul');for(const {message,field} of issues){const li=document.createElement('li');li.textContent=message;if(field){const jump=document.createElement('button');jump.type='button';jump.className='btn';jump.textContent='Ir al campo';jump.addEventListener('click',()=>{reveal(field);});li.append(' ',jump);}list.append(li);}status.append(list);}
 status.scrollIntoView?.({block:'nearest'});
}
// V38: nombres de grupos, validar antes de enviar sin sustituir datos silenciosamente.
const namingFields=[['ordinaryTemplate','Nombre grupo ordinario','{GRADO}{LETRA}'],['recoveryTemplate','Nombre recuperación','RE-P{PERIODO}-{CONSECUTIVO}'],['recourseTemplate','Nombre recursamiento','RC-{MATERIA}-{CONSECUTIVO}']];
function namingIssue(value){
 if(typeof value!=='string'||!value.length)return 'Escribe una plantilla.';
 if(value.length>80)return 'Máximo 80 caracteres.';
 const bad=Array.from(new Set([...value].filter(c=>!/^[A-Z0-9_{} -]$/.test(c))));
 if(bad.length)return 'Caracteres no permitidos: '+bad.slice(0,8).map(c=>'U+'+c.codePointAt(0).toString(16).toUpperCase().padStart(4,'0')).join(', ')+'. Usa mayúsculas, números, espacios, guiones y llaves.';
 const tokens=['TIPO','MATERIA','PERIODO','GRADO','TURNO','CONSECUTIVO','CICLO','LETRA'];
 const matches=[...value.matchAll(/\{([A-Z]+)\}/g)];
 const unknown=matches.find(m=>!tokens.includes(m[1]));if(unknown)return 'Variable desconocida: '+unknown[1];
 if(/[{}]/.test(value.replace(/\{([A-Z]+)\}/g,'')))return 'Llaves inválidas.';
 if(!matches.length)return 'Incluye al menos una variable, por ejemplo {GRADO}.';
 return null;
}
function resetNaming(){
 if(!confirm('¿Restablecer únicamente los tres nombres de grupo a sus valores predeterminados? El resto de la propuesta no cambiará.'))return;
 dirty=true;for(const [key,,value] of namingFields){const input=document.getElementById('jl_'+key);if(input)input.value=value;}
 const status=document.getElementById('jl_naming_status');if(status)status.textContent='Nombres restablecidos. Puedes guardar la propuesta.';
}
function saveIssues(form){
 const issues=[];
 const add=(message,field)=>issues.push({message,field});
 for(const field of form.elements){if(field.id==='jl_preview_grade'||!field.willValidate||field.validity.valid)continue;
  const row=field.closest('[data-curriculum-row]');const subject=row?.querySelector('[data-field="name"]')?.value.trim();
  const label=field.labels?.[0];const name=label?[...label.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim():field.id;
  add(`${subject?subject+' · ':''}${name||'Campo'}: ${field.validationMessage}`,field);
 }
 for(const [key,label,example] of namingFields){const field=form.querySelector('#jl_'+key);const error=namingIssue(field?.value);if(error)add(label+': '+error+' Ejemplo: '+example,field);}
 const reason=form.querySelector('#jl_reason');if(reason&&reason.value.trim().length<15&&reason.validity.valid)add('Motivo: escribe al menos 15 caracteres.',reason);
 for(const row of form.querySelectorAll('[data-curriculum-row]')){
  const total=row.querySelector('[data-field="totalMinutes"]'),name=row.querySelector('[data-field="name"]').value.trim()||'Asignatura sin nombre';
  const parts=[...row.querySelectorAll('[data-field^="periodMinutes"]')];
  if(total.validity.valid&&parts.every(x=>x.validity.valid)){
   const sum=parts.reduce((a,x)=>a+Number(x.value),0),target=Number(total.value);
   if(sum!==target)add(`${name}: los periodos suman ${sum} min y el total exigido es ${target} min. ${target>sum?'Faltan':'Sobran'} ${Math.abs(target-sum)} min. Corrige la distribución o el total según tu plan.`,total);
  }
 }
 return issues;
}
async function save(e){e.preventDefault();const form=e.currentTarget;if(pending){saveStatus(form,'Hay una operación en curso.');return;}
 const button=form.querySelector('button[type="submit"]');let submitted=false;
 try{
  const issues=saveIssues(form);if(issues.length){saveStatus(form,'No se guardó: revisa los siguientes campos.',issues);return;}
  const policy=readPolicy();const plan={cycle,policy,calendar:captureCalendar().slice(0,policy.periods),template:templateOrigin,curriculum:captureCurriculum()};const reason=document.getElementById('jl_reason').value;
  if(!confirm('¿Registrar propuesta? No cambiarán las calificaciones ni el ciclo activo.')){saveStatus(form,'Guardado cancelado. Tus datos siguen en el formulario.');return;}
  pending=true;submitted=true;if(button)button.disabled=true;saveStatus(form,'Registrando propuesta…');const c=cycle;
  await api('POST',{action:'proponer',cycle:c,version,plan,reason,confirmed:true});
  dirty=false;saveStatus(form,'Propuesta registrada correctamente.');
  if(S.page==='planificacion_360'&&form.isConnected){try{await loadPage('planificacion_360');toast('Propuesta registrada con historial.');}catch(err){saveStatus(form,'La propuesta se registró, pero no se pudo recargar la vista. Consulta el historial antes de volver a guardar.');}}
 }catch(err){saveStatus(form,'No se pudo guardar: '+(err?.message||'Error inesperado.'));}
 finally{if(submitted)pending=false;if(button)button.disabled=false;}}
async function approve(){if(pending)return;if(dirty&&!confirm('Hay cambios sin guardar. ¿Validar la última versión registrada, no los cambios del formulario?'))return;const reason=prompt('Motivo de validación (mínimo 15 caracteres)');if(!reason||reason.trim().length<15)return; if(!confirm('¿Validar únicamente para planificación?'))return;pending=true;try{await api('POST',{action:'validar',cycle,version,reason,confirmed:true});if(S.page==='planificacion_360'){await loadPage('planificacion_360');toast('Validación registrada.')}}catch(err){toast(err.message)}finally{pending=false}}
async function closure(){
 const target=document.getElementById('jl_closure');if(!target)return;
 target.textContent='Consultando los registros actuales…';
 try{
 const {data:{session}}=await supabaseClient.auth.getSession();if(!session?.access_token)throw Error('Inicia sesión de nuevo.');
 const r=await fetch('/api/academic-lifecycle?view=closure',{headers:{Authorization:'Bearer '+session.access_token}}),d=await jaguarReadJson(r);if(!r.ok||!d.ok)throw Error(d.error||'No fue posible consultar el diagnóstico.');
 if(!target.isConnected)return;const x=d.data;
 const n=v=>E(v??'—');
 target.innerHTML=`<div class="card space-y-3"><h3>Diagnóstico preliminar · ${E(x.ciclo)}</h3><p class="text-sm">Padrón actual: ${n(x.padron_actual_count)} alumnos. No certifica el padrón histórico ni las sesiones impartidas. No determina reprobación ni permite cerrar.</p>${Number(x.grupos_sin_materias)>0?`<p>Grupos con alumnos y sin materias activas: ${n(x.grupos_sin_materias)}.</p>`:''}${(x.periodos||[]).map(p=>`<details class="card"><summary>${E(p.nombre)} · ${p.captura_abierta?'Captura abierta':'Captura no habilitada'} · ${n(p.notas_pendientes_estimadas)} notas por revisar</summary><p class="text-sm">Notas esperadas estimadas: ${n(p.notas_esperadas_estimadas)}. Registros fuera del padrón actual: ${n(p.notas_fuera_padron_actual)}. Celdas sin asistencia en días observados: ${n(p.celdas_asistencia_pendientes)} de ${n(p.celdas_asistencia_observadas)}. Los días sin ningún registro aún no se pueden verificar.</p>${!p.fecha_inicio||!p.fecha_fin?'<p>Fechas incompletas: no se puede acotar la asistencia.</p>':''}<div class="scroll"><table class="table"><thead><tr><th>Grupo</th><th>Notas por revisar / esperadas</th><th>Asistencias sin registro / celdas observadas</th></tr></thead><tbody>${(p.grupos||[]).map(g=>`<tr><td>${E(g.clave)}</td><td>${n(g.notas_pendientes)} / ${n(g.esperadas)}</td><td>${n(g.asistencias_sin_registro)} / ${n(g.celdas_observadas)}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}<p><b>Cierre definitivo no disponible:</b> falta incorporar padrón histórico, sesiones y validaciones de acreditación.</p></div>`;
 }catch(e){if(target.isConnected)target.textContent=e.message;}
}
